import{_ as i,o as a,c as t,a2 as e}from"./chunks/framework.BU4O3IzQ.js";const c=JSON.parse('{"title":"「布局技巧」图片未加载前自动撑开元素高度","description":"","frontmatter":{"title":"「布局技巧」图片未加载前自动撑开元素高度","date":"2020-02-22T00:00:00.000Z","tags":["CSS"],"section":"ui"},"headers":[],"relativePath":"ui/css/布局技巧图片未加载前自动撑开元素高度.md","filePath":"ui/css/布局技巧图片未加载前自动撑开元素高度.md","lastUpdated":1786092171000}'),n={name:"ui/css/布局技巧图片未加载前自动撑开元素高度.md"};function p(l,s,h,d,k,r){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="「布局技巧」图片未加载前自动撑开元素高度" tabindex="-1">「布局技巧」图片未加载前自动撑开元素高度 <a class="header-anchor" href="#「布局技巧」图片未加载前自动撑开元素高度" aria-label="Permalink to &quot;「布局技巧」图片未加载前自动撑开元素高度&quot;">​</a></h1><p class="article-meta"><time datetime="2020-02-22">2020-02-22</time><span class="article-tag">CSS</span></p><p>在移动端开发中，有一些元素是根据图片高度来自动撑开的 ，高度不能写死（如轮播图的外层元素）。在网络较慢的情况下，图片加载需要一些时间，此时该元素的高度没有被撑开，在网页布局上会有一些不想看到的效果。</p><p>这种情况我们可以设置如下样式来设置该元素的高度：</p><div class="language-stylus vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">stylus</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.wrapper</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  overflow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> hidden</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  width</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  height</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  padding-bottom</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 26.66</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 这个数值是图片的高宽比，即 高/宽</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  background</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> #eee</span></span></code></pre></div><p>上面代码中，<code>padding-bottom</code> 的取值是图片的高宽比（即，高/宽），它会根据 <code>width</code>值的<code>26.66%</code>计算，最终元素的高度会和图片加载完成后的高度一致。</p><p>也可以使用<code>vw</code>的方法，但在一些浏览器可能有兼容性问题：</p><div class="language-stylus vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">stylus</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.wrapper</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  width</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  height</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 26.66</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">vw</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  background</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> #eee</span></span></code></pre></div><blockquote><p><code>vw</code>，viewpoint width，视窗宽度，1vw=视窗宽度的1%</p><p><code>vh</code>，viewpoint height，视窗高度，1vh=视窗高度的1%</p><p>更多 <a href="https://www.runoob.com/cssref/css-units.html" target="_blank" rel="noreferrer">CSS单位</a>。</p></blockquote>`,9)])])}const g=i(n,[["render",p]]);export{c as __pageData,g as default};
